// NOVEL — not generated by CLI Printing Press. See
// .printing-press-patches/garmin-sql-escape-hatch.json for why the press
// cannot express this command.
//
// `sql` is the archive's escape hatch. `insights` answers the two questions
// we knew to ask; this one answers the rest, because no recipe list covers
// every question somebody will have about their own years of data. The query
// itself makes no network call; the one network path is the root --deliver
// flag, which posts the finished envelope to the named sink after the query
// returns (root.go), exactly as on every other command. No query it runs can
// change the archive:
//
//  1. internal/sqlguard rejects anything that is not one SELECT or WITH
//     statement, after stripping the comments and semicolons SQLite itself
//     skips — so "-- x\nDROP TABLE resources" and "SELECT 1; ATTACH ..." are
//     refused by the same gate the MCP `sql` tool uses.
//  2. the handle is opened mode=ro with query_only, so a statement that
//     somehow got past the gate still answers SQLITE_READONLY rather than
//     writing. Neither layer is trusted alone: mode=ro does NOT stop
//     `ATTACH DATABASE` from creating a file, and a keyword prefix check does
//     not stop a leading comment.
//
// A third bound is about memory rather than writes: the result budget in
// internal/mcp/bound marshals a row before it measures it, so one oversized
// cell is built whole in this process before any cap applies. The connection
// this command queries on therefore carries SQLITE_LIMIT_LENGTH
// (garminSQLMaxCellBytes), so SQLite refuses such a value instead of
// allocating it.
//
// One disclosed side effect, and it is not the query's: resolving the default
// --db goes through garminArchivePath, the resolver `insights` and `history`
// share, which pins a data.db in a home that has none and renames a single
// token-scoped archive to the home's name. The store's own open then migrates
// that file, so what a run leaves behind in a fresh home is a migrated but
// empty archive — measured this build at 196608 bytes, 0 rows, and no
// garmin_series_state, the same footprint `insights` leaves. That happens
// before the query runs and is the same behaviour every archive-reading
// command has; --db <path> skips it entirely. The read-only open then creates
// the usual -shm and an empty -wal beside the file. None of it changes
// archived rows.
//
// pp:data-source local

package cli

import (
	"context"
	"database/sql"
	"fmt"
	"io"
	"os"
	"strings"

	"github.com/mvanhorn/printing-press-library/library/health/garmin/internal/mcp/bound"
	"github.com/mvanhorn/printing-press-library/library/health/garmin/internal/sqlguard"
	"github.com/spf13/cobra"
)

// garminSQLTables are the tables this help advertises. They are asserted
// against a freshly migrated store by test rather than copied from another
// CLI, so the help cannot promise a table this binary does not create.
var garminSQLTables = []struct {
	name string
	note string
}{
	{"resources", "every archived row: (resource_type, id, data JSON, synced_at, updated_at). id is the ISO date for a day-keyed series and the activity id for an activity-keyed one."},
	{"resources_fts", "FTS5 index over the same rows, for MATCH queries."},
	{"activities", "typed projection of the activity feed (activity_id, activity_name, duration, distance, average_hr, start_time_local, ...)."},
	{"sleep", "typed projection of the nightly sleep rows."},
	{"steps", "typed projection of the daily step rows."},
	{"training", "typed projection of the training-status rows."},
	{"wellness", "typed projection of the weekly intensity-minute rows."},
	{"account", "the cached account profile."},
	{"garmin_series_state", "one bookmark per series: last_complete_day, earliest_day, frontier_day, stop_reason, total_rows; created by the first history run, so a never-filled archive does not have it yet."},
	{"sync_state", "the generated per-resource cursor table."},
}

// garminSQLMaxCellBytes is this command's name for the per-value cap both
// read-only SQL surfaces share. Why 4 MiB, and why the result budget cannot do
// this job, is recorded once at sqlguard.MaxCellBytes.
const garminSQLMaxCellBytes = sqlguard.MaxCellBytes

// garminSQLEmptyHint names the command that fills the archive. It is the same
// sentence `insights` prints, for the same reason: no rows is a legitimate
// answer, never an error, and the caller needs to know what would change it.
const garminSQLEmptyHint = "hint: the local archive has no rows yet. Run '" + insightsSyncCommand + " --since all' to fill it."

func newGarminSQLCmd(flags *rootFlags) *cobra.Command {
	var dbPath string

	cmd := &cobra.Command{
		Use:   "sql <query>",
		Short: "Run one read-only SELECT against the local Garmin archive",
		// pp:happy-args gives the press's live matrix a query to run; without
		// it the matrix cannot fill the positional and never exercises sql.
		Annotations: map[string]string{
			"mcp:read-only": "true",
			"pp:happy-args": "<query>=SELECT resource_type, count(*) AS n FROM resources GROUP BY 1",
		},
		Long: `Ask the archive a question no built-in recipe covers.

The archive is one SQLite file that '` + insightsSyncCommand + `' fills. This
command opens it read-only and runs a single SELECT (or WITH ... SELECT)
against it. Anything else — INSERT, REPLACE, DROP, PRAGMA, ATTACH, VACUUM, a
second statement after a semicolon, a statement hidden behind a leading
comment — is refused before it reaches SQLite, and the handle it would have
reached is opened mode=ro with query_only, so no query can find a write path.

Tables:
` + garminSQLTableHelp() + `
Most series live only in ` + "`resources`" + `. Start with
'SELECT resource_type, count(*) FROM resources GROUP BY 1' to see what this
archive holds, then read fields out of the JSON with json_extract.

When a join keys on a value read out of the JSON, give each side its own
'WITH ... AS MATERIALIZED (...)' CTE: without MATERIALIZED, SQLite inlines the
CTE and re-parses every JSON row once per joined pair.

A query that itself starts with a SQL comment has to follow a bare --, or the
flag parser claims it as an unknown flag before this command sees it. Every
flag goes before that --: everything after it is the query, so a flag written
there is refused rather than joined onto the SQL as a comment.

An empty archive is not an error: the result is zero rows and a hint on stderr
naming the command that would fill it.`,
		Example: `  # What the archive holds
  garmin-pp-cli sql "SELECT resource_type, count(*) AS n FROM resources GROUP BY 1 ORDER BY 2 DESC"

  # json_extract, grouped by month
  garmin-pp-cli sql "SELECT substr(json_extract(data,'$.startTimeLocal'),1,7) AS month, count(*) AS activities, round(sum(json_extract(data,'$.duration'))/3600.0,1) AS hours FROM resources WHERE resource_type='activities' GROUP BY month ORDER BY month DESC LIMIT 12"

  # join two series on a value read out of the JSON, one materialized CTE per side
  garmin-pp-cli sql "WITH days AS MATERIALIZED (SELECT substr(json_extract(data,'$.startTimeLocal'),1,10) AS day, count(*) AS activities, round(sum(json_extract(data,'$.duration'))/3600.0,1) AS hours FROM resources WHERE resource_type='activities' GROUP BY 1), steps AS MATERIALIZED (SELECT id AS day, json_extract(data,'$.totalSteps') AS steps FROM resources WHERE resource_type='steps') SELECT d.day, d.activities, d.hours, s.steps FROM days d JOIN steps s ON s.day = d.day ORDER BY d.day DESC LIMIT 14" --agent`,
		Args: cobra.MinimumNArgs(1),
		RunE: func(cmd *cobra.Command, args []string) error {
			if err := garminSQLRejectTrailingFlags(args); err != nil {
				return err
			}
			// The words are rejoined rather than taking args[0] alone so a
			// caller whose quoting was eaten somewhere between the shell and
			// here still runs the query it wrote, instead of a truncated one.
			query := strings.TrimSpace(strings.Join(args, " "))
			return runGarminSQL(cmd, flags, dbPath, query)
		},
	}
	cmd.Flags().StringVar(&dbPath, "db", "", "SQLite database file path. The default is this home's data directory data.db, which is named for the home rather than for the credential in use, so a token refresh never orphans it; pass --db to read a different file.")
	return cmd
}

// garminSQLRejectTrailingFlags refuses a flag written after the query.
// Everything after the documented bare -- reaches this command as a
// positional, so `sql -- "SELECT 1" --agent` would otherwise join --agent onto
// the query, where SQLite reads it as a line comment: the query runs, the flag
// is silently dropped and the exit code is still 0. No flag on this CLI has a
// shorthand other than -h, so any argument after the query that begins with
// "-" is a misplaced flag rather than SQL.
func garminSQLRejectTrailingFlags(args []string) error {
	if len(args) < 2 {
		return nil
	}
	for _, arg := range args[1:] {
		if strings.HasPrefix(arg, "-") {
			return fmt.Errorf("%s follows the query, so it would be read as SQL rather than as a flag: every flag goes before the bare --, and everything after it is the query", arg)
		}
	}
	return nil
}

func garminSQLTableHelp() string {
	var b strings.Builder
	for _, t := range garminSQLTables {
		fmt.Fprintf(&b, "  %s — %s\n", t.name, t.note)
	}
	return b.String()
}

// garminSQLResult is the envelope both output paths share. It is this
// command's own shape, not a field-for-field mirror of the MCP sql tool:
// mcpSQLEnvelope (internal/mcp/tools.go) carries store_status, resumable and
// returned_count, and never max_rows. What the two do share is the bound that
// produced them — the same deadline, the same row and byte caps, and the same
// truncation note — so truncated, note and the cap named beside them mean the
// same thing on either surface.
type garminSQLResult struct {
	Count     int              `json:"count"`
	Columns   []string         `json:"columns"`
	Rows      []map[string]any `json:"rows"`
	Truncated bool             `json:"truncated"`
	MaxRows   int              `json:"max_rows,omitempty"`
	MaxBytes  int              `json:"max_bytes,omitempty"`
	Note      string           `json:"note,omitempty"`
	NextStep  string           `json:"next_step,omitempty"`

	// archiveEmpty records what the zero-row probe found on the query's own
	// handle. It is not part of the envelope; it only decides which hint the
	// caller prints.
	archiveEmpty bool
}

func runGarminSQL(cmd *cobra.Command, flags *rootFlags, dbPath, query string) error {
	if query == "" {
		return fmt.Errorf("a query is required, for example: %s sql \"SELECT resource_type, count(*) FROM resources GROUP BY 1\"", "garmin-pp-cli")
	}
	// The gate runs before the database is even located: a refused query must
	// not depend on whether an archive exists.
	if err := sqlguard.Validate(query); err != nil {
		return err
	}
	if dbPath == "" {
		dbPath = garminArchivePath(cmd.Context(), cmd.ErrOrStderr())
	}

	result, err := garminSQLQuery(cmd.Context(), dbPath, query)
	if err != nil {
		return err
	}

	if result.Count == 0 && !result.Truncated {
		if result.archiveEmpty {
			result.NextStep = garminSQLEmptyHint
			fmt.Fprintln(cmd.ErrOrStderr(), garminSQLEmptyHint)
		} else {
			result.NextStep = "The query returned no rows. Check the resource_type filter and the json_extract paths, or run '" + insightsSyncCommand + " --status' to see how far each series got."
		}
	}

	out := cmd.OutOrStdout()
	if wantsHumanTable(out, flags) {
		return printGarminSQLTable(out, result)
	}
	return printJSONFiltered(out, result, flags)
}

// garminSQLQuery opens the archive read-only and runs the query under the
// same deadline and row budget the MCP sql tool uses.
func garminSQLQuery(ctx context.Context, dbPath, query string) (garminSQLResult, error) {
	db, err := openGarminArchiveReadOnly(ctx, dbPath)
	if err != nil {
		return garminSQLResult{}, err
	}
	defer db.Close() //nolint:errcheck // read-only handle

	// The cell cap binds to one connection, so the query runs on the
	// connection that carries it rather than on whichever one the pool hands
	// out. The handle allows a single connection, so this one is also the only
	// one: every later read here goes through it, not through db.
	conn, err := garminSQLConn(ctx, db)
	if err != nil {
		return garminSQLResult{}, err
	}
	defer conn.Close() //nolint:errcheck // read-only connection

	queryCtx, cancel := bound.WithSQLQueryDeadline(ctx)
	defer cancel()

	rows, err := conn.QueryContext(queryCtx, query)
	if err != nil {
		return garminSQLResult{}, garminSQLQueryError(queryCtx, err)
	}
	defer rows.Close() //nolint:errcheck // read-only query

	cols, err := rows.Columns()
	if err != nil {
		return garminSQLResult{}, fmt.Errorf("reading columns: %w", err)
	}
	scan := bound.NewSQLScanState(cols)
	for rows.Next() {
		values := make([]any, len(cols))
		ptrs := make([]any, len(cols))
		for i := range values {
			ptrs[i] = &values[i]
		}
		if err := rows.Scan(ptrs...); err != nil {
			return garminSQLResult{}, fmt.Errorf("scanning row: %w", err)
		}
		row := make(map[string]any, len(cols))
		for i, col := range cols {
			row[col] = garminSQLValue(values[i])
		}
		if !scan.Add(row) {
			break
		}
	}
	// rows.Next() stops on a mid-iteration error without failing the loop, so
	// skipping rows.Err() would report a truncated result set as success.
	if err := rows.Err(); err != nil {
		return garminSQLResult{}, garminSQLQueryError(queryCtx, err)
	}

	result := garminSQLResult{
		Count:     len(scan.Rows),
		Columns:   cols,
		Rows:      scan.Rows,
		Truncated: scan.Truncated,
	}
	if result.Rows == nil {
		result.Rows = []map[string]any{}
	}
	if len(scan.Rows) == 0 && !scan.Truncated {
		// Asked on the handle this query already holds: whether the archive is
		// empty or the query simply did not match decides which hint the
		// caller prints, and a second open of a live WAL database to count
		// rows buys nothing.
		result.archiveEmpty = garminArchiveIsEmpty(ctx, conn)
	}
	if result.Columns == nil {
		result.Columns = []string{}
	}
	if scan.Truncated {
		// Only the cap that actually stopped the scan is named. The byte
		// budget fires first at any realistic row size (SQLScanState.Add
		// rejects on bytes and treats SQLMaxRows as a backstop), so reporting
		// max_rows on every truncation would name a cap the result never
		// reached.
		if len(scan.Rows) >= bound.SQLMaxRows {
			result.MaxRows = bound.SQLMaxRows
		} else {
			result.MaxBytes = bound.MaxBytes
		}
		result.Note = bound.SQLResultBoundNote
	}
	return result, nil
}

// openGarminArchiveReadOnly opens the archive with no write path.
//
// mode=ro makes SQLite refuse every write at the driver level, including the
// CTE-wrapped write the statement gate deliberately lets through, and
// query_only refuses one layer above that so the answer is the same on a
// handle somebody later opens read-write by mistake.
//
// immutable=1 is deliberately NOT set. immutable=1 tells SQLite the file has
// no WAL to consult; against a live archive that is false, and it was
// measured (this build, on a WAL fixture with a writer connection open) to
// report "no such table" for a table that exists and to miss a committed row
// that had not been checkpointed. A query that silently drops today's rows is
// worse than one that waits on a lock, so this handle reads the WAL and
// busy_timeout covers the contention. store.OpenReadOnlyContext opens the
// same way since N131.5.5 (it carried immutable=1 until then, which is what
// made the MCP sql and search tools answer from a stale snapshot), so the DSN
// here and the store's are deliberately the same shape.
func openGarminArchiveReadOnly(ctx context.Context, dbPath string) (*sql.DB, error) {
	if _, err := os.Stat(dbPath); err != nil {
		if os.IsNotExist(err) {
			return nil, fmt.Errorf("no local archive at %s. Run '%s --since all' to create it", dbPath, insightsSyncCommand)
		}
		return nil, fmt.Errorf("checking local archive %s: %w", dbPath, err)
	}
	dsn := "file:" + dbPath + "?mode=ro&_pragma=query_only(true)&_pragma=busy_timeout(5000)&_pragma=foreign_keys(ON)&_pragma=temp_store(MEMORY)&_pragma=mmap_size(0)"
	db, err := sql.Open("sqlite", dsn)
	if err != nil {
		return nil, fmt.Errorf("opening local archive %s (read-only): %w", dbPath, err)
	}
	db.SetMaxOpenConns(1)
	if err := db.PingContext(ctx); err != nil {
		_ = db.Close()
		return nil, fmt.Errorf("opening local archive %s (read-only): %w", dbPath, err)
	}
	return db, nil
}

// garminSQLConn checks out the connection the query will run on and caps the
// length of any value SQLite will build on it. The cap itself is
// sqlguard.CapConn, which the MCP `sql` tool calls too; this name stays
// because the cases that prove the cap is on the query's own connection call
// it directly. openGarminArchiveReadOnly allows a single connection, so on
// this path the capped one is also the only one.
func garminSQLConn(ctx context.Context, db *sql.DB) (*sql.Conn, error) {
	return sqlguard.CapConn(ctx, db)
}

// garminArchiveIsEmpty reports whether the archive holds no rows at all, so
// "no rows" can be answered with the hint that names the fill command rather
// than with a hint about the caller's WHERE clause. A missing resources table
// is a database that was never filled, which is the same answer. Any other
// failure reads as not-empty, which leaves the caller with the hint about its
// own query — the safe answer when the probe itself could not speak.
func garminArchiveIsEmpty(ctx context.Context, conn *sql.Conn) bool {
	var n int
	if err := conn.QueryRowContext(ctx, `SELECT count(*) FROM resources`).Scan(&n); err != nil {
		return isMissingArchive(err)
	}
	return n == 0
}

// garminSQLValue makes a scanned SQLite value honest in JSON. TEXT and BLOB
// arrive as []byte, which encoding/json would base64 into an unreadable
// string; JSON payloads are the common case here, so text stays text.
func garminSQLValue(v any) any {
	raw, ok := v.([]byte)
	if !ok {
		return v
	}
	return string(raw)
}

func garminSQLQueryError(queryCtx context.Context, err error) error {
	if isSQLValueTooBig(err) {
		return fmt.Errorf("query failed: %w. One value in the result was longer than the %d MiB per-value cap this command sets, so SQLite refused to build it rather than holding it in memory; ask for a slice instead — substr(data,1,4000), json_extract(data,'$.field'), or a narrower LIMIT", err, garminSQLMaxCellBytes>>20)
	}
	if queryCtx.Err() != nil {
		return fmt.Errorf("query cancelled: %w. Queries are bounded to %s; narrow it with WHERE, GROUP BY, or an aggregate", err, bound.SQLQueryTimeout)
	}
	if strings.Contains(strings.ToLower(err.Error()), "no such table") {
		return fmt.Errorf("query failed: %w. Most archived rows live in resources(resource_type, id, data), not one table per series: filter by resource_type and read fields with json_extract(data,'$.field'). Run 'garmin-pp-cli sql --help' for the table list", err)
	}
	return fmt.Errorf("query failed: %w", err)
}

// isSQLValueTooBig reports whether SQLite refused a value for exceeding
// SQLITE_LIMIT_LENGTH. The test itself is sqlguard.IsValueTooBig, shared with
// the MCP `sql` tool so both surfaces recognise the same refusal.
func isSQLValueTooBig(err error) bool {
	return sqlguard.IsValueTooBig(err)
}

// printGarminSQLTable prints the same tab-separated shape the generated
// commands and `insights` print. Column order comes from the query, not from
// map iteration, so two runs of one query print identically.
func printGarminSQLTable(w io.Writer, result garminSQLResult) error {
	if len(result.Columns) == 0 || result.Count == 0 {
		fmt.Fprintln(w, "0 rows")
		if result.NextStep != "" {
			fmt.Fprintf(w, "%s\n", result.NextStep)
		}
		return nil
	}
	fmt.Fprintln(w, strings.Join(result.Columns, "\t"))
	dashes := make([]string, len(result.Columns))
	for i := range dashes {
		dashes[i] = "-----"
	}
	fmt.Fprintln(w, strings.Join(dashes, "\t"))
	for _, row := range result.Rows {
		cells := make([]string, 0, len(result.Columns))
		for _, col := range result.Columns {
			cells = append(cells, formatInsightValue(row[col]))
		}
		fmt.Fprintln(w, strings.Join(cells, "\t"))
	}
	fmt.Fprintf(w, "\n%d rows\n", result.Count)
	if result.Truncated {
		fmt.Fprintf(w, "%s\n", result.Note)
	}
	return nil
}
